import 'dart:async';import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:firebase_messaging/firebase_messaging.dart';class NotificationService{final _db=FirebaseFirestore.instance;Future<void> initialize()async{final u=FirebaseAuth.instance.currentUser;if(u==null)return;await FirebaseMessaging.instance.requestPermission();final token=await FirebaseMessaging.instance.getToken();if(token!=null)await _db.collection('users').doc(u.uid).collection('devices').doc(token).set({'token':token,'updatedAt':FieldValue.serverTimestamp()});FirebaseMessaging.instance.onTokenRefresh.listen((t)=>_db.collection('users').doc(u.uid).collection('devices').doc(t).set({'token':t,'updatedAt':FieldValue.serverTimestamp()}));}Stream<int> unreadCount(){final u=FirebaseAuth.instance.currentUser?.uid;if(u==null)return Stream.value(0);return _db.collection('chats').where('participants',arrayContains:u).snapshots().map((s)=>s.docs.where((d)=>d.data()['unreadFor']==u).length);}Stream<int> announcementCount()=>_db.collection('announcements').where('active',isEqualTo:true).snapshots().map((s)=>s.docs.length);}Stream<int> reportCount()=>_db.collection('reports').where('status',isEqualTo:'open').snapshots().map((s)=>s.docs.length);}